import{_ as r,o as e,c as a,a2 as o}from"./chunks/framework.CG3qCjiJ.js";const c=JSON.parse('{"title":"如何启用SA帐号","description":"","frontmatter":{"title":"如何启用SA帐号","date":"2026-10-14T16:03:16.000Z","lastmod":"2026-11-25T14:19:06.000Z"},"headers":[],"relativePath":"guide/1114.md","filePath":"guide/帮助文档/安装卸载说明/网络版安装相关问题说明/如何启用SA帐号.md"}'),s={name:"guide/1114.md"};function n(i,t,l,S,g,_){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="如何启用sa帐号" tabindex="-1">如何启用SA帐号 <a class="header-anchor" href="#如何启用sa帐号" aria-label="Permalink to &quot;如何启用SA帐号&quot;">​</a></h1><h1 id="如何在现有的数据库服务器上启用sa帐号" tabindex="-1">如何在现有的数据库服务器上启用Sa帐号 <a class="header-anchor" href="#如何在现有的数据库服务器上启用sa帐号" aria-label="Permalink to &quot;如何在现有的数据库服务器上启用Sa帐号&quot;">​</a></h1><p>如果在安装过程中选择“Windows 身份验证模式”,没有选择混合模式,则 SQL 身份验证被关闭,sa帐号也被禁用,要启用SA帐号,需要安装SQL Server Management Studio 对象资源管理器**,<strong>并执行更改命令</strong>,<strong>过程比较麻烦</strong>,<strong>不容易掌握</strong>,**</p><p><strong>建议采用如下任意一种方案</strong></p><ul><li><strong>重新安装SqlServer的方式比较方便,先在控制面板中删除SqlServer,然后再执行</strong>SqlServer<strong>安装程序</strong>,<strong>此时再设置为混合模式</strong>,<strong>并设置</strong>Sa<strong>的密码即可</strong>,</li><li><strong>先在控制面板中删除SqlServer,,然后</strong>重新执行Entis主程序安装文件,在安装过程中勾选&quot;<strong>是否按照默认配置自动安装SqlServer2017数据库</strong>&quot;,勾选后,默认安装的数据库实例有默认的sa帐号</li></ul>',5)])])}const u=r(s,[["render",n]]);export{c as __pageData,u as default};
